  const [selectedDeviceIds,setSelectedDeviceIds]=useState<Set<string>>(new Set());
  const [selectedAssignmentIds,setSelectedAssignmentIds]=useState<Set<string>>(new Set());
  const [interfaceEditorMode,setInterfaceEditorMode]=useState<'create'|'edit'|'bulk'>('create');
  const [selectedInterfaces,setSelectedInterfaces]=useState<Set<string>>(new Set());
  const [interfaceRoceEnabled,setInterfaceRoceEnabled]=useState(true);
  const [interfacePfcEnabled,setInterfacePfcEnabled]=useState(false);
  const [interfaceQuery,setInterfaceQuery]=useState('');
  const [deviceQuery,setDeviceQuery]=useState('');
  const [deviceRoleFilter,setDeviceRoleFilter]=useState<'All'|'Spine'|'Leaf'>('All');
  const [interfaceStateDraft,setInterfaceStateDraft]=useState<Record<string,InterfacePolicyState>>({});
  const [interfaceModalError,setInterfaceModalError]=useState('');
  const [bulkInterfaceMenu,setBulkInterfaceMenu]=useState<'roce'|'pfc'|null>(null);
  const [roleTab,setRoleTab]=useState<'Spine'|'Leaf'>('Spine');
  const [modelTab,setModelTab]=useState('');
  const [pfcDraft,setPfcDraft]=useState<PfcRow>({id:'',roceQueue:3,headroom:1024,guaranteed:256,sharedRatio:100,resetOffset:128});
