  const fabricDevices=useMemo(()=>inventoryState.registered.filter(device=>fabricRoleIds.Spine.has(device.id)||fabricRoleIds.Leaf.has(device.id)),[fabricRoleIds,inventoryState.registered]);
  const roleDevices=useMemo(()=>fabricDevices.filter(device=>fabricRoleIds[roleTab].has(device.id)),[fabricDevices,fabricRoleIds,roleTab]);
  const roleModels=useMemo(()=>[...new Set(roleDevices.map(device=>device.model))],[roleDevices]);
