  const legacyRoleModel=roleDevices[0]?.model;
  const templateKey=roleTab;
  const activeTemplate=draft.templates[templateKey]||(legacyRoleModel?draft.templates[`${roleTab}:${legacyRoleModel}`]:undefined)||defaultTemplate(templateKey);
  const selectedDevices=fabricDevices.filter(device=>selectedDeviceIds.has(device.id));
  const firstSelectedDevice=selectedDevices[0];
  const observedInterfaces=useMemo(()=>{if(!firstSelectedDevice)return[];return [...new Set(inventoryState.connections.flatMap(link=>[link.source===firstSelectedDevice.id?link.sourceInterface:'',link.target===firstSelectedDevice.id?link.targetInterface:'']).filter(Boolean) as string[])].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}))},[firstSelectedDevice,inventoryState.connections]);
  const availableInterfaces=useMemo(()=>{if(!firstSelectedDevice)return[];const generated=Array.from({length:Math.min(firstSelectedDevice.interfaces,64)},(_,index)=>`Ethernet${index+1}`);return[...new Set([...observedInterfaces,...generated])]},[firstSelectedDevice,observedInterfaces]);
  const filteredInterfaces=availableInterfaces.filter(name=>name.toLowerCase().includes(interfaceQuery.toLowerCase()));
