  const assignedInterfaceCount=new Set(draft.interfaceAssignments.flatMap(row=>row.interfaceNames.map(name=>`${row.deviceId}:${name}`))).size;
  const visibleAssignmentIds=draft.interfaceAssignments.filter(row=>inventoryState.registered.some(device=>device.id===row.deviceId)).map(row=>row.deviceId);
  const allVisibleAssignmentsSelected=visibleAssignmentIds.length>0&&visibleAssignmentIds.every(id=>selectedAssignmentIds.has(id));
  const toggleAllAssignments=()=>setSelectedAssignmentIds(current=>{const next=new Set(current);visibleAssignmentIds.forEach(id=>allVisibleAssignmentsSelected?next.delete(id):next.add(id));return next});
  const toggleAssignment=(deviceId:string)=>setSelectedAssignmentIds(current=>{const next=new Set(current);next.has(deviceId)?next.delete(deviceId):next.add(deviceId);return next});
  const modified=Boolean(!draft.lastAppliedAt);
  const update=<K extends keyof RocePolicyDraft>(key:K,value:RocePolicyDraft[K])=>{onDraftChange(current=>({...current,[key]:value,lastAppliedAt:undefined}));setMessage('')};
  const updateTemplate=(transform:(current:SwitchTemplate)=>SwitchTemplate)=>{onDraftChange(current=>{const base=current.templates[templateKey]||(legacyRoleModel?current.templates[`${roleTab}:${legacyRoleModel}`]:undefined)||defaultTemplate(templateKey);return{...current,templates:{...current.templates,[templateKey]:transform(base)},lastAppliedAt:undefined}});setMessage('')};

  const openQueue=(row?:QueueRow)=>{setEditingId(row?.id);setQueueDraft(row?{...row,roceQueue:draft.trustMode==='802.1q'?'':row.roceQueue,weight:row.schedulingMode==='SP'?'':row.weight||'1',guaranteedRate:row.guaranteedRate||''}:draft.trustMode==='DSCP'?{id:rowId('queue'),roceQueue:3,dscpValues:'26',schedulingMode:'WRR',weight:'1',guaranteedRate:''}:{id:rowId('queue'),roceQueue:'',dscpValues:'',schedulingMode:'WRR',weight:'1',guaranteedRate:''});setModal('queue')};
  const queueErrors=(()=>{const errors:Partial<Record<'roceQueue'|'dscpValues'|'weight'|'guaranteedRate',string>>={};const serviceText=queueDraft.dscpValues.trim();const dscpPattern=/^\d+(?:\s*,\s*\d+)*$/;const dscp=parseDscp(serviceText);if(!serviceText)errors.dscpValues=`${draft.trustMode==='DSCP'?'DSCP':'802.1q'} Values of Service Packets is required.`;else if(draft.trustMode==='DSCP'&&!dscpPattern.test(serviceText))errors.dscpValues='Use comma-separated integers, for example: 3, 26, 27.';else if(draft.trustMode==='DSCP'&&dscp.some(value=>!Number.isInteger(value)||value<0||value>63))errors.dscpValues='Permitted range: 0–63.';else if(draft.trustMode==='DSCP'&&new Set(dscp).size!==dscp.length)errors.dscpValues='DSCP values must be unique.';else if(draft.trustMode==='802.1q'&&!/^[0-7]$/.test(serviceText))errors.dscpValues='Select an 802.1q value from 0 to 7.';if(draft.trustMode==='DSCP'&&queueDraft.roceQueue==='')errors.roceQueue='RoCE Queue is required.';else if(queueDraft.roceQueue!==''&&draft.queueRows.some(row=>row.id!==editingId&&row.roceQueue===queueDraft.roceQueue))errors.roceQueue=`RoCE Queue ${queueDraft.roceQueue} already exists.`;if(queueDraft.schedulingMode!=='SP'&&queueDraft.weight.trim()){const weight=Number(queueDraft.weight);if(!Number.isInteger(weight)||weight<1||weight>15)errors.weight='Enter an integer from 1 to 15.'}if(queueDraft.schedulingMode==='WFQ'){const guaranteedRate=Number(queueDraft.guaranteedRate);if(!queueDraft.guaranteedRate.trim())errors.guaranteedRate='Guaranteed Rate is required.';else if(!Number.isInteger(guaranteedRate)||guaranteedRate<8||guaranteedRate>40000000)errors.guaranteedRate='Enter an integer from 8 to 40000000.'}return errors})();
  const queueError=Object.values(queueErrors)[0]||'';
  const saveQueue=()=>{if(queueError)return;const value={...queueDraft,weight:queueDraft.schedulingMode==='SP'?'':queueDraft.weight.trim()||'1',guaranteedRate:queueDraft.schedulingMode==='WFQ'?queueDraft.guaranteedRate:''};update('queueRows',editingId?draft.queueRows.map(row=>row.id===editingId?value:row):[...draft.queueRows,value]);setModal(null)};
  const openInterfaces=()=>{setInterfaceEditorMode('create');setSelectedDeviceIds(new Set());setSelectedInterfaces(new Set());setInterfaceStateDraft({});setDeviceQuery('');setDeviceRoleFilter('All');setInterfaceQuery('');setInterfaceModalError('');setBulkInterfaceMenu(null);setModal('interfaces')};
  const saveInterfaces=()=>{if(!selectedDeviceIds.size||!selectedInterfaces.size)return;const names=[...selectedInterfaces];const states=Object.fromEntries(names.map(name=>[name,interfaceStateDraft[name]||{roceEnabled:false,pfcEnabled:false}]));if(Object.values(states).some(state=>state.pfcEnabled&&!state.roceEnabled)){setInterfaceModalError('You must enable RoCE before enabling PFC.');return}const selectedIds=new Set(selectedDeviceIds);const retained=draft.interfaceAssignments.filter(row=>!selectedIds.has(row.deviceId));const values=Object.values(states);const rows=[...selectedIds].map(deviceId=>({deviceId,interfaceNames:names,interfaceStates:states,roceEnabled:values.some(state=>state.roceEnabled),pfcEnabled:values.some(state=>state.pfcEnabled)}));update('interfaceAssignments',[...retained,...rows]);setSelectedAssignmentIds(new Set());setModal(null)};
  const loadInterfaceEditor=(rows:InterfaceAssignment[],mode:'edit'|'bulk')=>{if(!rows.length)return;const source=rows[0];const states=Object.fromEntries(source.interfaceNames.map(name=>[name,source.interfaceStates?.[name]||{roceEnabled:source.roceEnabled,pfcEnabled:source.pfcEnabled}]));setInterfaceEditorMode(mode);setSelectedDeviceIds(new Set(rows.map(row=>row.deviceId)));setSelectedInterfaces(new Set(source.interfaceNames));setInterfaceStateDraft(states);setDeviceQuery('');setDeviceRoleFilter('All');setInterfaceQuery('');setInterfaceModalError('');setBulkInterfaceMenu(null);setModal('interfaces')};
  const editInterfaces=(row:InterfaceAssignment)=>loadInterfaceEditor([row],'edit');
  const bulkEditInterfaces=()=>loadInterfaceEditor(draft.interfaceAssignments.filter(row=>selectedAssignmentIds.has(row.deviceId)),'bulk');
  const bulkDeleteInterfaces=()=>{if(!selectedAssignmentIds.size)return;update('interfaceAssignments',draft.interfaceAssignments.filter(row=>!selectedAssignmentIds.has(row.deviceId)));setSelectedAssignmentIds(new Set())};
  const savePfc=()=>{const rows=editingId?activeTemplate.pfcRows.map(row=>row.id===editingId?pfcDraft:row):[...activeTemplate.pfcRows,{...pfcDraft,id:pfcDraft.id||rowId('pfc')}];updateTemplate(current=>({...current,pfcRows:rows}));setModal(null)};
  const saveWred=()=>{if(wredDraft.minThreshold>wredDraft.maxThreshold||wredDraft.dropProbability<0||wredDraft.dropProbability>100)return;const rows=editingId?activeTemplate.wredRows.map(row=>row.id===editingId?wredDraft:row):[...activeTemplate.wredRows,{...wredDraft,id:wredDraft.id||rowId('wred')}];updateTemplate(current=>({...current,wredRows:rows}));setModal(null)};
  const cnpValueMax=draft.trustMode==='DSCP'?63:7;
